"""Three focused import types per module; fields are an explicit write allowlist."""
from dataclasses import dataclass, field
from importlib import import_module


def f(key, label=None, type="text", required=False, sample="", aliases=()):
    return dict(key=key, label=label or key.replace("_", " ").title(), type=type, required=required, sample=sample, aliases=list(aliases))


@dataclass
class ImportSpec:
    module: str
    key: str
    label: str
    model_path: str
    fields: list
    identity: tuple
    permissions: tuple
    defaults: dict = field(default_factory=dict)
    note: str = ""

    @property
    def model(self):
        module, name = self.model_path.rsplit(".", 1)
        return getattr(import_module(module), name)


